```hcl
# Deny requests that do not use SSL/TLS
resource "aws_sqs_queue_policy" "<example_resource_name>" {
  queue_url = aws_sqs_queue.<example_resource_name>.url
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Deny"
      Principal = "*"
      Action    = "sqs:*"
      Resource  = aws_sqs_queue.<example_resource_name>.arn
      Condition = {
        Bool = {
          "aws:SecureTransport" = "false" # Critical: deny requests not using SSL/TLS
        }
      }
    }]
  })
}
```
